syntax:
switch (expression) {        // int or char only
    case value1:             // value1 must be a constant
        statements;
        break;               // leave the switch
    case value2:
        statements;
        break;
    case value3:             // no break here: falls into the next case
    case value4:             // value3 and value4 share these statements
        statements;
        break;
    default:                 // runs when no case matches (optional)
        statements;
}

sample.code:
#include <iostream>
using namespace std;

int main() {
    int day;
    cin >> day;
    switch (day) {
        case 1:
            cout << "Monday" << endl;
            break;
        case 2:
            cout << "Tuesday" << endl;
            break;
        case 3:
            cout << "Wednesday" << endl;
            break;
        default:
            cout << "Invalid day number" << endl;
    }
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    double a, b;
    char op;
    cin >> a >> op >> b;
    switch (op) {
        case '+': cout << "Result = " << a + b << endl; break;
        case '-': cout << "Result = " << a - b << endl; break;
        case '*': cout << "Result = " << a * b << endl; break;
        case '/':
            if (b != 0) {
                cout << "Result = " << a / b << endl;
            } else {
                cout << "Error: division by zero" << endl;
            }
            break;
        default:
            cout << "Unknown operator" << endl;
    }
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    char ch;
    cin >> ch;
    switch (ch) {
        case 'a':
        case 'A':
        case 'e':
        case 'E':
        case 'i':
        case 'I':
        case 'o':
        case 'O':
        case 'u':
        case 'U':
            cout << "Vowel" << endl;
            break;
        default:
            cout << "Consonant" << endl;
    }
    return 0;
}

