#include <iostream>
using namespace std;
int main() {
    int choice;
    cin >> choice;
    switch (choice) {
        case 1:
            cout << "Price: Rs 250" << endl;
            break;
        case 2:
            cout << "Price: Rs 800" << endl;
            break;
        case 3:
            cout << "Price: Rs 50" << endl;
            break;
        default:
            cout << "Invalid choice" << endl;
    }
    return 0;
}
